<script setup lang="ts">import{onMounted,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import{api}from'../../api/client';import type{DirectoryItem}from'../../domain/types';const items=ref<DirectoryItem[]>([]),loading=ref(true),error=ref('');onMounted(async()=>{try{items.value=(await api.getDirectory()).filter(i=>i.publicationState==='ELIGIBLE')}catch{error.value='暂时无法读取信息，请稍后重试'}finally{loading.value=false}});function open(i:DirectoryItem){uni.setStorageSync('directoryItem',i);uni.navigateTo({url:'/pages/directory/detail'})}</script>
<template><view class="page"><AppHeader left="首页" @left="uni.reLaunch({url:'/pages/index/index'})"/><view class="content"><view class="heading" role="heading" aria-level="1">在孟实用信息</view><text class="desc">查看生活服务与办事信息，使用前请留意更新时间。</text><view v-if="loading" class="card" role="status">正在加载…</view><view v-if="error" class="card" role="alert">{{error}}</view><button v-for="item in items" :key="item.contentRef" class="card item" :aria-label="`查看信息 ${item.title}`" @click="open(item)"><view class="avatar">孟</view><view class="item-copy"><text class="card-title">{{item.title}}</text><text class="copy">{{item.category}} · 更新于 {{item.updatedAt}}</text></view><text class="arrow">›</text></button><view v-if="!loading&&!error&&!items.length" class="card empty">暂时没有可展示的信息。</view></view></view></template><style src="../../styles/shared.css"></style><style scoped>.item{width:100%;display:flex;align-items:center;text-align:left}.avatar{width:80rpx;height:80rpx;border-radius:22rpx;background:#fff3e8;color:#9a531d;font-weight:900;display:flex;align-items:center;justify-content:center;flex:none}.item-copy{flex:1;margin-left:20rpx}.arrow{font-size:42rpx;color:var(--muted);margin-left:16rpx}.empty{text-align:center;color:var(--muted)}</style>
